local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[8446] = { title = "Eingehüllt in Alpträume", description = "Dunkelheit umgibt dieses Objekt.\n\nVielleicht gibt es eine Verbindung zwischen diesem Gegenstand und den aus dem Traum vordringenden Drachen. Sucht nach jemandem, der die Bedeutung dieses Gegenstands entschlüsseln kann. Vielleicht können Euch die Druiden der Mondlichtung oder ihre Vertreter auf Burg Cenarius weiterhelfen.", objectives = "Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.\n\nVielleicht kann Euch ein Druide von großer Macht weiterhelfen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8447] = { title = "Legenden erwachen", description = "Das Wasser des Sees von Elune'ara wird die Alpträume auflösen, die den Gegenstand umgeben. Bitte, gebt mir einen Moment, um die Reinigung durchzuführen, $n.", objectives = "Wartet, bis Bewahrer Remulos bei der Mondlichtung den von Alpträumen eingehüllten Gegenstand gereinigt hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8460] = { title = "Verbündeter der Holzschlundfeste", description = "Die Furbolgs der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Einwohner der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet die Krieger, Pfadfinder und Gärtner der Totenwaldfelle im Süden.", objectives = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8461] = { title = "Totenwaldfelle des Nordens", description = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.\n\nDer Stamm der Totenwaldfelle ist böse, aber die Verderbnis ist es, die ihre Hirne verseucht. Ihre Feindseligkeit ist keine angeborene Eigenschaft, doch da kann man nichts machen. Aus diesem Grund stimmt es mich zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss.\n\nBitte, $n, tut, was getan werden muss, aber erspart mir die Einzelheiten. Sie beunruhigen mich zu sehr.", objectives = "Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8462] = { title = "Sprecht mit Nafien", description = "Vielleicht seid Ihr stark genug, um Euch einer noch größeren Bedrohung entgegenzustellen. Die Furbolgs der Holzschlundfeste brauchen Eure Hilfe und ich denke, Ihr habt hier bereits Eure Tauglichkeit im Kampf ausreichend bewiesen. Reist auf dieser Straße in Richtung Norden, bis zum Eingang der Holzschlundfeste, wo einer meiner Brüder Wache steht. Sein Name ist Nafien. Im ersten Augenblick mag er vielleicht wie ein ungezügeltes, wildes Tier wirken, doch braucht Ihr ihn nicht zu fürchten. Er ist auf der Suche nach tapferen Abenteurern, die ihm im Kampf gegen die dunklen Verderbnis unterstützen, welche unsere Heimat bedroht.", objectives = "Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8464] = { title = "Aktivität der Winterfelle", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, $n. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber, wenn möglich, andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nEs stimmt mich zwar zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss, trotzdem möchte ich Euch bitten, dass Ihr einige von ihnen ausmerzt, um die Bedrohung, die von ihnen ausgeht, zu verringern. Ihr findet sie im Lager der Winterfelle.", objectives = "Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich genau außerhalb des Eingangs zur Holzschlundfeste in Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8465] = { title = "Sprecht mit Salfa", description = "Die Verderbnis bedroht uns nicht nur in Form der Totenwaldfelle vom Süden her, sondern auch durch die Winterfellfurbolgs im Osten. Wenn Ihr uns auch weiterhin helfen wollt, sprecht mit Salfa auf der anderen Seite der Festung. Ihr findet sie nahe des Eingangs zu Winterspring. Folgt einfach dem linken Pfad, um zu ihr zu gelangen.\n\nDoch seid gewarnt! Sollten meinesgleichen Euch gegenüber hasserfüllt oder gar feindlich eingestellt sein, werden sie Euch angreifen. Sollte dies der Fall sein, durchquert das Gebiet schnellstmöglich und vermeidet alle Kämpfe mit ihnen. Einen Furbolg der Holzschlundfeste zu töten und sei es nur zur Selbstverteidigung, wird Euren Ruf in der Holzschlundfeste nur weiter verschlechtern.", objectives = "Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8466] = { title = "Federn für Grazle", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8467] = { title = "Federn für Nafien", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8469] = { title = "Perlen für Salfa", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8470] = { title = "Ritualtotem der Totenwaldfelle", description = "Ihr habt ein Ritualtotem der Totenwaldfelle gefunden. Das Totem selbst ist von unbestimmbarer Machart, aber es geht eine spürbare Verzweiflung davon aus. Gäbe es auch nur eine einzige Sache, die die Verderbnis der Totenwaldfelle veranschaulichen könnte, so wäre es mit Sicherheit dieses Totem.\n\nEiner der Furbolgs innerhalb der Holzschlundfeste könnte vielleicht eine Verwendung für diesen Gegenstand haben... gesetztenfalls Ihr habt Euch genug Vertrauen verdient, um mit ihnen zu sprechen.", objectives = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8471] = { title = "Ritualtotem der Winterfelle", description = "Ihr habt ein Ritualtotem der Winterfellfurbolgs gefunden. Das Totem selbst ist von unbestimmbarer Machart, aber es geht eine beinahe greifbare Aura der Furcht und Verzweiflung von ihm aus. Sollten tatsächlich alle Furbolgs der Winterfelle ein solches Totem bei sich tragen, würde dies ihren momentanen Zustand sicherlich erklären.\n\nEiner der Furbolgs innerhalb der Holzschlundfeste könnte vielleicht eine Verwendung für diesen Gegenstand haben... gesetztenfalls Ihr habt Euch genug Vertrauen verdient, um mit ihnen zu sprechen.", objectives = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8481] = { title = "Die Wurzel alles Bösen", description = "$n, dank Euch haben wir eine Möglichkeit ausfindig gemacht, wie wir die Wurzel alles Bösen der Winterfelle beschwören können - den Dämon der Verderbnis, der sie beherrscht!\n\nBringt diese Fackel zum Eingang von Grolnars persönlicher Höhle und stellt sie dort auf. Der Dämon wird sich dadurch zu erkennen geben und nachforschen müssen. Das ist der Moment, in dem Ihr und Eure Verbündeten zuschlagen müsst! Ausschließlich die Essenz des gefallenen Dämonen wird den langwierigen Heilungsprozess des Winterfellstammes in Gang setzen... und die Erlösung der Holzschlundfeste und ihrer Einwohner.", objectives = "Stellt die Fackel zur Dämonenbeschwörung im Eingang von Grolnars Höhle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8484] = { title = "Das Bemühen um Frieden", description = "Eure Taten gehen weit über die Geschichte eines einfachen Helden hinaus, $n. Solltet Ihr der Vertreter Eures Volkes sein, dann sind dies diejenigen, mit denen wir, dem Frieden zu Willen, gerne zusammenarbeiten würden.\n\nBitte - bringt dies als Zeichen unseres Friedens zu dem Zwergenkönig, der in einem Berg aus Eisen lebt; ich glaube man nennt diese Stadt Eisenschmiede. In vergangenen Zeiten hatte er im Namen seiner Allianz versucht, mit uns Kontakt aufzunehmen. Es bietet sich jetzt also an, Euch als Schlüssel hinsichtlich der Friedensbemühungen Eurer Allianz zu betrachten.", objectives = "Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebart in Eisenschmiede.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8485] = { title = "Das Bemühen um Frieden", description = "Eure Taten gehen weit über die Geschichte eines einfachen Helden hinaus, $n. Solltet Ihr der Vertreter Eures Volkes sein, dann sind dies diejenigen, mit denen wir, dem Frieden zu Willen, gerne zusammenarbeiten würden.\n\nBitte, bringt dies als Zeichen unseres Friedens zu dem Kriegshäuptling der Orcs, der in den Landen von Durotar lebt; ich glaube man nennt die Stadt Orgrimmar. In vergangenen Zeiten hatte er im Namen seiner Horde versucht, mit uns Kontakt aufzunehmen. Es bietet sich jetzt also an, Euch als Schlüssel hinsichtlich der Friedensbemühungen Eurer Horde zu betrachten.", objectives = "Bringt das Friedensangebot der Holzschlundfeste zu Shok Narnes in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8492] = { title = "Die Allianz braucht Kupferbarren!", description = "Hey, $C, Ihr seht tauglich genug aus, um zu den Kriegsanstrengungen beizutragen! Wir brauchen jede Hilfe, die wir bekommen können, um die benötigten Vorräte für den Krieg in Ahn'Qiraj zusammenzutragen. Heute ist Euer Glückstag.\n\nIch sammle Kupferbarren in Stapeln zu je 20 Stück. Der Zweck ist die Mühe wert, was denkt Ihr? Sicherlich wollt Ihr die Allianz unterstützen!", objectives = "Bringt 20 Kupferbarren zu Sergeant Stonebrow im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8493] = { title = "Die Allianz braucht mehr Kupferbarren!", description = "Wieder zurück, $C? Exzellent! Solltet Ihr noch mehr Stapel Kupferbarren aufbringen können, wir benötigen noch immer welche für die Vorbereitungen des Krieges in Ahn'Qiraj. Wie sieht's aus, seid Ihr dabei?", objectives = "Bringt 20 Kupferbarren zu Unteroffizier Steinbraue beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8494] = { title = "Die Allianz braucht Eisenbarren!", description = "Ihr da, seid gegrüßt, $g Herr Modenarr: Frau Modenärrin;, was für eine Augenweide Ihr doch seid. Solltet Ihr es, während Ihr auf \"Abenteuern\" wart, noch nicht gehört haben: die Allianz macht sich für den Krieg in Ahn'Qiraj bereit und braucht dringend Eisenbarren... eine ganze Menge davon. Bringt sie in Stapeln zu je 20 Stück zu mir. Wir können doch auf Euch zählen, oder $C?", objectives = "Bringt 20 Eisenbarren zu Corporal Carnes im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8495] = { title = "Die Allianz braucht mehr Eisenbarren!", description = "Schon wieder da? Hört auf, mich meine geringe Meinung von Euch noch einmal überdenken zu lassen, $C, Ihr macht mich ja ganz gefühlsduselig. Naja, wie Ihr sehen könnt, haben wir noch immer nicht genug Eisenbarren für die Herstellung aller Waffen, Rüstungen, Dampfpanzer und was auch immer für diese Käferjagd noch gebraucht wird. Könntet Ihr vielleicht noch einmal 20 Eisenbarren während Eurer Abenteuerei in Zul'Gurub, oder wo Ihr Bengel Euch dieser Tage sonst noch herumtreibt, besorgen?", objectives = "Bringt 20 Eisenbarren zu Korporal Schwarz beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8496] = { title = "Verbände für den Feldeinsatz", description = "Nach den neusten Verlusten, die wir hinnehmen mussten, gehen unsere Vorräte an Verbänden für das Schlachtfeld gefährlich zur Neige. Besorgt Euch eine Ladung an Vorräten für Erste Hilfe und bringt sie zu Windruferin Prachthorn auf Burg Cenarius.", objectives = "Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8497] = { title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", objectives = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8498] = { title = "Zwielichtschlachtbefehle", description = "Unsere Späher haben berichtet, dass die Anführer des Schattenhammers neue Schlachtbefehle ausgegeben haben. Die Befehle wurden von Propheten des Schattenhammers unter schwerem Geleitschutz verteilt. Fangt die Schlachtbefehle ab und bringt sie zu Kommandant Mar'alith.", objectives = "Beschafft Euch die Schlachtbefehle des Schattenhammers und bringt sie zu Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch den taktischen Einsatz X, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8499] = { title = "Die Allianz braucht Thoriumbarren!", description = "Es ist äußerst freundlich, dass Ihr Euch nach den Bedürfnissen der Allianz erkundigt. Zusätzlich zu all den anderen Sammelaktionen, die gerade im Gange sind, benötigen wir noch jede Menge Thoriumbarren. Damit wurde ich beauftragt. Thorium wird der Herstellung von vielerlei Kriegsmaterialien dienen, vor allem aber dem Aufbau eines Bataillons von Dampfpanzern, die nach ihrer Fertigstellung per Lufttransport nach Silithus gebracht werden sollen. Könntet Ihr uns bei diesem Unterfangen behilflich sein, $C?", objectives = "Bringt 20 Thoriumbarren zu Dame Twinbraid im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8500] = { title = "Die Allianz braucht mehr Thoriumbarren!", description = "Schön, Euch wiederzusehen, $n. Ich hoffe es ist Euch gut ergangen. Es stimmt, wir benötigen noch immer Thoriumbarren. Solltet Ihr welche entbehren können, ich sammle sie hier für die Kriegsvorbereitungen von Ahn'Qiraj.", objectives = "Bringt 20 Thoriumbarren zu Dame Doppelzopf beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8501] = { title = "Ziel: Stecher des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die fliegenden Stecher des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", objectives = "Tötet 30 Stecher des Ashischwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XII, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8502] = { title = "Ziel: Arbeiter des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Arbeiter des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", objectives = "Tötet 30 Arbeiter des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz III, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8503] = { title = "Die Allianz braucht Würgetang!", description = "So $C, habe ich Euch schon von all den wunderbaren Verwendungszwecken erzählt, die Würgetang bietet? Ja? Oh, na dann... wir brauchen auf jeden Fall eine Menge davon, und wenn ich eine Menge sage, dann meine ich eine große Menge! Meint Ihr, dass Ihr uns helfen könntet? Ich weiß, dass das bedeutet, dass Ihr daraus nichts Tolles für Euch selbst herstellen könnt, aber es ist für einen guten Zweck!", objectives = "Bringt 20 Stück Würgetang zu dem Gefreiten Draxlegauge im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8504] = { title = "Die Allianz braucht mehr Würgetang!", description = "Hallo Ihr... warum seid Ihr nochmal hier? Ah... natürlich, $n! Ihr seid gekommen, um nachzusehen, ob ich noch mehr Würgetang brauche, oder? Na dann ist heute Euer Glückstag, denn die Antwort auf diese wichtige Frage lautet eindeutig JA! Könntet Ihr vielleicht noch einmal zwanzig mehr sammeln?", objectives = "Bringt 20 Stück Würgetang zu dem Gefreiten Drechselknacks beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8505] = { title = "Die Allianz braucht lila Lotus!", description = "$C, lila Lotus ist eine Pflanze, die vielfach verwendet werden kann. Ich bin hier im Auftrag der Allianz und verantwortlich dafür, dass die gesammelten Pflanzen sicher aufbewahrt und ihrem vorgesehenen Verwendungszweck im Rahmen unserer Kriegsbemühungen zugeführt werden.\n\nIch würde Euch gerne damit beauftragen durch die Welt zu ziehen und zu mir zurückzukehren, sobald Ihr einige dieser Pflanzen gesammelt habt. Wäre das machbar?", objectives = "Bringt 20 lila Lotus zu Meister Nightsong im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8506] = { title = "Die Allianz braucht mehr lila Lotus!", description = "Seid gegrüßt, $C. Unsere Sammlung wächst zwar, aber wir brauchen auch weiterhin noch lila Lotus. Wenn Ihr glaubt, noch mehr dieser Pflanzen beschaffen zu können, dann bitte ich Euch inständig dies zu tun und damit anschließend zu mir zurückzukehren.", objectives = "Bringt 20 lila Lotus zu Meister Nachtweise beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8507] = { title = "Felddienst", description = "Seid gegrüßt, $n. Bevor ich Euch mit umfassenderen Aufgaben in diesem Krieg beauftrage, müsst Ihr Euren Anteil am Felddienst leisten.\n\nIhr könnt die Eisenschmiedebrigade von Hauptmann Rußschmied außerhalb des Zoraschwarmbaus finden.\n\nErstattet ihm oder seinem Leutnant, Janela Starkhammer, Bericht und kommt dann wieder zu mir. Ich werde wichtigere Anweisungen für Euch bereithalten.\n\nOh, bitte erweist uns den Gefallen und haltet Euch von der Orgrimmarlegion fern. Wir sind gezwungen die beiden Streitkräfte aufgrund gegenseitiger Feindseligkeit auseinander zu halten.", objectives = "Erstattet am Posten der Eisenschmiedebrigade beim Zoraschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie von Hauptmann Rußschmied unterzeichnen und kehrt zu Windrufer Kaldon auf Burg Cenarius in Silithus zurück.\n\nHinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Eisenschmiedebrigade wird Euch für den PvP-Kampf markieren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8508] = { title = "Felddienstpapiere", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8509] = { title = "Die Allianz braucht Arthas' Tränen!", description = "Ich möchte nicht lange darum herum reden $C. Die Allianz benötigt eine große Menge an Arthas' Tränen für die Kriegsanstrengungen von Ahn'Qiraj. Fragt mich nicht für was; ich befolge nur Anweisungen. Trotzdem würde ich Euch gerne bitten, so viele dieser Pflanzen wie möglich zu sammeln und sie anschließend hierher zu mir zu bringen. Würdet Ihr das tun?", objectives = "Bringt 20 Arthas' Tränen zu Sergeant Major Germaine im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8510] = { title = "Die Allianz braucht mehr Arthas' Tränen!", description = "Ok, es sieht so aus, als ob ich noch mehr Arthas' Tränen benötigen würde. Ich könnte mir vorstellen, dass Ihr sie dort wiederfindet, wo Ihr sie auch schon das letzte Mal für mich gesammelt habt. Umso schneller wir sie beisammen haben, desto schneller können wir unsere Offensive in Ahn'Qiraj beginnen.\n\nHelft Ihr uns noch einmal, $C?", objectives = "Bringt 20 Arthas' Tränen zu Stabsfeldwebel Germaine beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8511] = { title = "Die Allianz braucht leichtes Leder!", description = "Wir Stoneflayers können auf eine lange Geschichte der Kürschnerei zurückblicken, $C. Deshalb hat die Allianz auch meine Familie damit beauftragt, bei der Sammlung von leichtem Leder für die Kriegsanstrengungen von Ahn'Qiraj mitzuhelfen. Ich achte darauf, dass das Leder vernünftig gegerbt wird. Was danach daraus gemacht wird, weiß ich nicht. Wir brauchen jedoch Eure Hilfe.\n\nDa ich wegen meiner Arbeit hier bleiben muss, brauche ich Euch, um die Häute zu beschaffen und sie anschließend zu mir zu bringen. Was meint Ihr $g Junge : Mädel;, seid Ihr dabei?", objectives = "Bringt 10 Einheiten leichtes Leder zu Bonnie Stoneflayer im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8512] = { title = "Die Allianz braucht mehr leichtes Leder!", description = "Schön, Euch wiederzusehen, $n. Es scheint, als würden wir noch mehr leichtes Leder für die Herstellung verschiedenster Kriegsmaterialien benötigen. Es wäre großartig, wenn ihr mir noch einmal einen Stapel mit zehn Stücken bringen könntet.", objectives = "Bringt 10 Einheiten leichtes Leder zu Bonnie Steinschinder beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8513] = { title = "Die Allianz braucht mittleres Leder!", description = "Ja $g mein Herr : meine Dame;, ich wurde mit der Sammlung und Aufbewahrung des mittleren Leders für die Kriegsvorbereitungen beauftragt. Solltet Ihr über die Mittel verfügen, um mittleres Leder besorgen zu können, woher auch immer, dann bringt es bitte zu mir. Ich könnte mit Sicherheit etwas Unterstützung gebrauchen, wenn Ihr Zeit habt.", objectives = "Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8514] = { title = "Die Allianz braucht mehr mittleres Leder!", description = "Ja, $gmein Herr:meine Dame;, es sieht aus als hätten wir bis zum heutigen Tag $2063w Stücke mittleren Leders gesammelt. Ich weiß es ist viel verlangt, aber wenn Ihr noch immer gewillt seid, dann könnte ich Eure Hilfe beim Zusammentragen des restlichen Leders noch einmal gebrauchen.", objectives = "Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8515] = { title = "Die Allianz braucht dickes Leder!", description = "Junge, Junge, das wird großartig! $C, die Vorbereitungen für den Krieg in Ahn'Qiraj sind in vollem Gange und man hat mich damit beauftragt sämtliche Ladungen an dickem Leder zu überwachen, die hier abgeliefert werden. Wir fertigen zahlreiche Dinge daraus an, aber zuallererst brauchen wir eine große Menge davon. Eine gewaltige Menge! Jetzt zu Euch.\n\nGlaubt Ihr, dass Ihr losziehen und mir einen fetten Stapel dickes Leder beschaffen könntet? Ja, wirklich?!", objectives = "Bringt 10 Einheiten dickes Leder zu Marta Finespindle im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8516] = { title = "Die Allianz braucht mehr dickes Leder!", description = "Tja, der Stapel ist noch nicht hoch genug. $n, wir haben noch immer nicht unsere Anforderung von $2071w Einheiten dicken Leders erreicht. Denkt nur an all die Dinge, die wir aus dem benötigten Leder noch herstellen können! Allerlei Rüstungen und Waffen. Sachen für das Innere der Dampfpanzer und Zubehör für Gewehre! Ingenieursbrillen und am Ende, wenn wir tatsächlich zu viel gesammelt haben, dient es auch noch als Material für die Zeppeline der Horde!\n\nBringt Ihr mir noch mehr dickes Leder?", objectives = "Bringt 10 Einheiten dickes Leder zu Marta Feinspindel beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8517] = { title = "Die Allianz braucht Leinenverbände!", description = "Der Krieg in Ahn'Qiraj wird lange und blutig sein. Es ist sehr weise, dass die Allianz Eure Hilfe und die von anderen Euresgleichen in Anspruch nimmt, um vorerst die benötigten Mittel zu erstellen, anstelle sich sofort in den Konflikt zu stürzen.\n\nIch wurde mit dem Sammeln von Leinenverbänden für den Krieg beauftragt und hoffe nun, dass Ihr mir bei dieser Aufgabe zu Hand gehen werdet. Wir brauchen so viele Verbände wie möglich. Es ist keine leichte Aufagbe, ich weiß, aber wenigstens lassen sich Leinenverbände am einfachsten herstellen. Seid Ihr dabei, $C?", objectives = "Bringt 20 Leinenverbände zu Schildwache Silversky im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8518] = { title = "Die Allianz braucht mehr Leinenverbände!", description = "Ich bin immer wieder von der Selbstlosigkeit überrascht, die an den Tag gelegt wird, denn andere würden an gleicher Stelle reine Selbstsucht walten lassen. $C, ich brauche immer noch eine gewisse Anzahl an Leinenverbänden, um meinen Auftrag hier zu erfüllen. Würdet Ihr mir noch einmal beim Sammeln dieser Verbände helfen?", objectives = "Bringt 20 Leinenverbände zu Schildwache Silberwolke beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8519] = { title = "Eine Spielfigur auf dem Schachbrett der Ewigkeit", description = "Als Ihr Eure Fassung wieder gewinnt und Ihr Euren Blick fokussiert, fällt Euch auf, dass sich etwas innerhalb des Kristalls bewegt. Nach genauerer Betrachtung wird Euch klar, dass Ihr gerade in die Vergangenheit seht... eine Erinnerung... seit langer Zeit vergessen.", objectives = "Lernt so viel Ihr könnt über die Vergangenheit, sprecht dann mit Anachronos in den Höhlen der Zeit in Tanaris.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8520] = { title = "Die Allianz braucht Seidenverbände!", description = "Mit dem immer näherrückenden Krieg in Ahn'Qiraj gilt es alles erdenkliche zu tun, um unsere Soladten mit allem zu versorgen, das sie brauchen werden. Wir kümmern uns hier genau um diese Sache. Ich bin verantwortlich für das Ansammeln von Seidenstoffverbänden.\n\nGlaubt Ihr, dass Ihr mir dabei helfen könntet, $C?", objectives = "Bringt 20 Seidenverbände zu Schwester Stonefield im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8521] = { title = "Die Allianz braucht mehr Seidenverbände!", description = "Es ist äußerst freundlich von Euch, mir erneut Eure Hilfe anzubieten, $C. Es sieht so aus, als hätten wir $2082w Seidenverbände gesammelt. Wir bräuchten daher noch mehr.", objectives = "Bringt 20 Seidenverbände zu Schwester Steinfeld beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8522] = { title = "Die Allianz braucht Runenstoffverbände!", description = "$C, stellt die Verdienste des Krieges in Frage, wenn Ihr wollt, er hat jedoch schon längst begonnen. Seht Euch bei Eurer Familie oder Euren Freunden um und fragt Euch dann, was es ist, das Ihr tun könnt, um im Fall der Fälle zu ihrem Überleben beizutragen.\n\nIch sammle hier Runenstoffverbände jeglicher Herkunft. Würdet Ihr gerne welche spenden?", objectives = "Bringt 20 Runenstoffverbände zu Bewahrer Moonshade im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8523] = { title = "Die Allianz braucht mehr Runenstoffverbände!", description = "Wir treffen also erneut aufeinander, um wichtige Angelegenheiten zu besprechen, $C. Ich möchte Euch noch einmal für Eure bisherigen Bemühungen danken; nicht jeder ist so selbstlos wie Ihr. Es gibt jedoch noch mehr zu tun.\n\nWürdet Ihr noch einmal Runenstoffverbände für mich sammeln gehen und sie dann zu mir bringen, $n?", objectives = "Bringt 20 Runenstoffverbände zu Bewahrer Mondschatten beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8524] = { title = "Die Allianz braucht Regenbogenflossenthunfisch!", description = "Hey, Ihr da! Wenn ich zu Euch sagen würde 'Sollten Soldaten nicht etwas zu essen haben, wie jeder andere auch?', dann würdet Ihr natürlich 'Ja!' sagen. Da stimme ich 110% mit Euch überein! Schön, dass wir uns einig sind. Es gibt nur eine Sache, um die ich Euch gerne bitten würde: zieht los, fischt eine ordentliche Menge Regenbogenflossenthunfische, kocht diese dann und bringt sie zu mir zurück. Mmm, mmm, ich kann es bereits schmecken.", objectives = "Bringt 20 Regenbogenflossenthunfische zu Gastronom Slicky im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8525] = { title = "Die Allianz braucht mehr Regenbogenflossenthunfisch!", description = "Was! Ihr seid schon wieder da? Naja, in der Kürze liegt ja bekanntlicherweise die Würze... ich als Gnom muss es ja wissen, Gastronom Glitschko genaugenommen! Ihr seid also wieder da, um auch weiterhin auszuhelfen? Nun, ich kann es Euch nicht verdenken. Liebt Ihr nicht ganz einfach den Duft von all diesem Essen? <lechz>\n\nGenug getrödelt! Geht jetzt los und fangt mehr Regenbogenflossenthunfisch für mich!", objectives = "Bringt 20 Regenbogenflossenthunfische zu Gastronom Glitschko beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8526] = { title = "Die Allianz braucht geröstete Raptoren!", description = "Oh, wie geht's $C? Ich sehe, dass Ihr eventuell beim Sammeln von Lebensmittelvorräten für den aufziehenden Krieg in Ahn'Qiraj mithelfen möchtet. Mein Vater hat sich wohl gedacht, dass es eine gute Lernerfahrung für mich wäre, wenn ich mich als freiwillige Aushilfe hier melde. Ein großer Fehler. Ich esse noch nicht einmal Fleisch.\n\nEgal, wenn Euch danach ist, dann könntet Ihr mir eine Menge gerösteter Raptoren bringen. Scheinbar ist das genau die Sache, nach der alle Soldaten verlangen.", objectives = "Bringt 20 geröstete Raptoren zu Sarah Sadwhistle im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8527] = { title = "Die Allianz braucht mehr geröstete Raptoren!", description = "Hallo nochmal, $C. Wie ich sehen kann, macht Euch die Sache richtig Spaß. Meiner Vermutung nach wollt Ihr mir also nochmal zwanzig geröstete Raptoren bringen. Großartig. Dann macht mal. Wir sehen uns, wenn Ihr wieder zurück seid.", objectives = "Bringt 20 geröstete Raptoren zu Sarah Sorgenpfeifer beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8528] = { title = "Die Allianz braucht Tüpfelgelbschwänze!", description = "Das Sammeln von gekochtem Fisch mag zwar nicht sehr heldenhaft erscheinen, aber Ihr solltet die Wichtigkeit von guten Vorbereitungen nicht unterschätzen, $C. Soldaten müssen eben essen, wie jeder andere auch. Wir leisten hierfür unseren Teil, um sicherzustellen, dass sie mit allem versorgt sind, das sie brauchen, sobald der Krieg in Ahn'Qiraj beginnt.\n\nFolglich sorge ich hier für die Einlagerung von Tüpfelgelbschwänzen, eine vielseitige Nahrungsressource, die sich gut lagern lässt und auf verschiedenste Art und Weise zubereitet werden kann. Der Geruch ähnelt zudem nicht dem von anderen Salzwasserfischen. Wollt Ihr mir bei dieser Unternehmung behilflich sein?", objectives = "Bringt 20 Tüpfelgelbschwänze zu Jägerin Swiftriver im Militärviertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8529] = { title = "Die Allianz braucht mehr Tüpfelgelbschwänze!", description = "Wenn Ihr noch immer gewillt seid, dann würde ich Euch gerne aussenden, um einen weiteren Schwung Tüpfelgelbschwänze zu beschaffen, $n. Ich vermute, dass es nach der Erfahrung, die Ihr beim ersten Mal gesammelt habt, diesmal wesentlich schneller und einfacher für Euch sein wird. Seid Ihr dabei?", objectives = "Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach beim Landeplatz in Dun Morogh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8532] = { title = "Die Horde braucht Kupferbarren!", description = "Ich bin froh, dass Ihr Euch entschieden habt hier auszuhelfen. Nicht jeder würde das tun, deshalb ist es auch wichtig, dass Ihr wirklich versteht, was ich hier brauche. Kupferbarren, nicht Kupfererz. Wir haben weder die Zeit, noch genügend Leute, um das Material hier selbst zu verhütten, wenn Ihr also so freundlich wäret und diesen Vorgang für uns übernehmen würdet. Man würde Eure Mühen an den richtigen Stellen zur Kenntnis nehmen. Was sagt Ihr dazu, $C?", objectives = "Bringt 20 Kupferbarren zu Minenarbeiter Cromwell im Tal der Geister in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8533] = { title = "Die Horde braucht mehr Kupferbarren!", description = "Schon wieder da? Ihr werdet in kürzester Zeit noch zum richtigen Bergarbeiter, $C. So, Ihr wisst Bescheid. Zieht los, baut jede Menge Kupfererz ab, verhüttet es in Barren und bringt diese dann hierher zu mir. Ich weiß, dass Ihr es könnt, die Frage ist nur, ob Ihr dazu auch gewillt seid?", objectives = "Bringt 20 Kupferbarren zu Minenarbeiter Kromwell in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8534] = { title = "Späherbericht des Zoraschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Azenel hat die Aktivitäten der Silithiden im Zoraschwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, $n.", objectives = "Setzt Euch mit der cenarischen Späherin Azenel innerhalb des Zoraschwarmbaus in Verbindung und bringt den Späherbericht des Zoraschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VI, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8535] = { title = "Weißgrauer Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten, stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj, können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen weißgrauen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", objectives = "Beschwört und vernichtet einen weißgrauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz IV, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8536] = { title = "Irdener Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen irdenen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", objectives = "Beschwört und vernichtet einen irdenen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz III, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8537] = { title = "Purpurroter Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen purpurroten Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", objectives = "Beschwört und vernichtet einen purpurroten Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz II, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8538] = { title = "Die vier Fürsten", description = "Die Verbindungen zwischen dem Schattenhammer und dem Abyssischen Rat scheinen bedeutsamer zu sein, als wir erwartet hätten.\n\nMan sagt, dass die Elementarfürsten, auch bekannt als die abyssischen Fürsten, ein Teil der treibenden Kräfte hinter den Kultisten des Schattenhammers sind. Findet einen Weg, um die vier abyssischen Fürsten auf unsere Existenzebene zu locken und zerstört sie!\n\nIhr habt in den vorangegangenen Einsätzen Eigeninitiative und Mut bewiesen, daher wurdet Ihr für den heutigen Auftrag ausgewählt. Wir sind sehr zuversichtlich, dass Ihr auch diesen Einsatz meistern werdet.", objectives = "Findet einen Weg, um den Fürst der Asche, den Fürst der Tiefen, den Fürst der Stürme und den Fürst der Splitter zu beschwören und zu vernichten. Erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz V, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8539] = { title = "Ziel: Schwestern des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Schwestern des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", objectives = "Tötet 30 Schwestern des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz V, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8540] = { title = "Stiefel für die Wache", description = "Die berittene Einheit der Wache von Burg Cenarius hat kaum noch Vorräte an verschnörkelten Mithrilstiefeln. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", objectives = "Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8541] = { title = "Schleifsteine für die Wache", description = "Die Wache von Burg Cenarius hat kaum noch Vorräte an Schleifsteinen. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", objectives = "Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8542] = { title = "Die Horde braucht Zinnbarren!", description = "Lok-Tar $R! Sicher habt Ihr schon von dem aufziehenden Krieg gegen die Insekten in Ahn'Qiraj gehört. Doch bevor wir losziehen, hat der Kriegshäuptling vorerst entschieden sogenannte 'Vorbereitungen' zu treffen. Obwohl ich viel lieber stumpfe Waffen schärfen oder Rüstungen wieder in Form bringen würde, ist mir die ehrenvolle Aufgabe übertragen worden, die Sammlung von Zinnbarren zu überwachen.\n\nDas bedeutet, dass ich Eure Hilfe brauche und dass Ihr für mich losziehen müsst, um Zinnbarren aufzutreiben und hierher zu mir zu bringen. Ich denke, dass ich mehr brauchen werde, als ich zählen kann.", objectives = "Bringt 20 Zinnbarren zu Grunzer Maug im Tal der Geister in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8543] = { title = "Die Horde braucht mehr Zinnbarren!", description = "Sehr gut, ich denke, Ihr versteht den Ernst des Krieges. Das Warten auf den Auftakt macht mich ganz nervös, was bedeutet, dass ich sehr verärgert sein werde, wenn Ihr mir nicht schneller mehr der Ressourcen bringt. Vielleicht sollte ich mich auch ganz einfach an Euch üben.\n\nHarr! Besser nicht, wer sollte mir denn sonst die Zinnbarren bringen?", objectives = "Bringt 20 Zinnbarren zu Grunzer Maug in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8544] = { title = "Schiftung des Eroberers", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", objectives = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8545] = { title = "Die Horde braucht Mithrilbarren!", description = "$C, der Krieg rückt näher und das Einzige, was wir tun können, ist uns darauf vorzubereiten. Hierbei können wir uns gegenseitig helfen. Seht Ihr, ich wurde mit der Sammlung von Mithrilbarren beauftragt, die wir zur Herstellung von allerlei Kriegsbedarf benötigen. Es fehlt noch eine ganze Menge!\n\nSo, ich hoffe Ihr zieht jetzt los, baut so viel Mithrilerz ab wie Ihr könnt und verhüttet es zu Mithrilbarren. Könntet Ihr das für uns tun?", objectives = "Bringt 20 Mithrilbarren zu Schlachtrufer T'kelah im Tal der Geister in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8546] = { title = "Die Horde braucht mehr Mithrilbarren!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8548] = { title = "Schlachtrüstung des Kriegsfreiwilligen", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, $n.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", objectives = "Bringt 5 cenarische Gefechtsabzeichen, 3 cenarische Versorgungsabzeichen und 7 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf beim Zirkel des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8549] = { title = "Die Horde braucht Friedensblumen!", description = "Man sagt, dass sich jede Generation einer bestimmten Prüfung stellen muss. Ich fürchte, dass der Krieg von Ahn'Qiraj genau das Ereignis ist, in dem unser Eifer auf die Probe gestellt wird. Wir bereiten uns deshalb vor, und finden dabei heraus, was uns wirklich ausmacht.\n\nIch habe mich freiwillig gemeldet, um der Horde beim Sammeln von so vielen Friedensblumen wie möglich zu helfen. Diese können dann in Tränke für den Kriegseinsatz verarbeitet werden. Ich hoffe, dass Ihr hier seid, um mir behilflich zu sein. Wenn ja, dann bringt mir eine gute Menge dieser Pflanzen. Werdet Ihr mich unterstützen, $C?", objectives = "Bringt 20 Friedensblumen zu der Kräuterkundigen Proudfeather im Tal der Geister in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8550] = { title = "Die Horde braucht mehr Friedensblumen!", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8551] = { title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratchet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Booty Bay gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!\n\nIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", objectives = "Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8552] = { title = "Die Schärpe mit Monogramm", description = "Auf dem Saum dieser feinen Schärpe sind die Buchstaben \"HS\" eingestickt.", objectives = "Bringt die Schärpe mit Monogramm zu ihrem Besitzer zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8553] = { title = "Der Entersäbel des Kapitäns", description = "Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Sprogger. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.", objectives = "Sprecht mit Sprogger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8554] = { title = "Negolash entgegentreten", description = "Negolash ist ein hungriger Riese.\n\nAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!\n\nWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!", objectives = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.\n\nTötet Negolash und bringt Smotts' Entersäbel zu Captain Smotts ins Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8555] = { title = "Der Bund der Drachenschwärme", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8556] = { title = "Siegel der unnachgiebigen Stärke", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, $C.", objectives = "Bringt 1 Gebieterring der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8557] = { title = "Tuch der unnachgiebigen Stärke", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, $n. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, $C.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", objectives = "Bringt 1 Kampftuch der Qiraji, 2 Onyxgötzen, 5 Sillberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8558] = { title = "Sichel der unnachgiebigen Stärke", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, $n, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", objectives = "Bringt 1 Stachelgriff der Qiraji, 2 Alabastergötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8559] = { title = "Schienbeinschützer des Eroberers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", objectives = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Krieges, 5 Elfenbeinskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8560] = { title = "Beinschützer des Eroberers", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", objectives = "Bringt Ouros intakte Haut, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8561] = { title = "Krone des Eroberers", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, $n. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", objectives = "Bringt Vek'nilashs Reif, 2 Götzen der Sonne, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8562] = { title = "Brustplatte des Eroberers", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", objectives = "Bringt den Knochenpanzer des Alten Gottes, 2 Götzen des Krieges, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8565] = { title = "Vergangene Siege im Arathibecken", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
