quests[8697] = { title = "Ring der unendlichen Weisheit", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, $C.", objectives = "Bringt 1 Zeremonienring der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
